var i=[{title:`Gelenke und wie sie sich bewegen`,text:`Der Ellbogen funktioniert hauptsächlich wie ein Scharnier und erlaubt Beugung und Streckung. Schulter und Hüfte sind Kugelgelenke, die sich in mehrere Richtungen bewegen können. Die Wirbelsäule hat viele Gelenke, und ihre gemeinsame Bewegung hilft bei der Positionierung und der Lastübertragung. Echte Gelenkbewegung ist nie ganz so einfach wie eine Lehrbuchzeichnung.`},{title:`Bewegungsumfang (ROM)`,text:`Der aktive ROM ist der Bereich, den du mit deinen eigenen Muskeln erreichen kannst. Der passive ROM ist der Bereich, den du mit fremder Hilfe erreichen kannst, und er kann größer sein. Ein begrenzter aktiver Bereich kann von Schwäche, Geschick, Steifheit, Schmerz oder einer Mischung davon kommen, „verkürzte Muskeln“ sind also nicht immer die ganze Geschichte. Körperproportionen und Gelenkstruktur beeinflussen ebenfalls, wie tief sich eine Übung bequem anfühlt.`},{title:`Volle und partielle Wiederholungen`,text:`Eine volle Wiederholung nutzt den geplanten, sicheren Bereich dieser Übung. Sie bedeutet nicht, das Gelenk an seine anatomische Grenze zu zwingen. Die Evidenz stützt in vielen Situationen Training durch einen vollständigen Bereich, den du kontrollieren kannst, und partielle Wiederholungen können helfen, wenn sie gezielt geplant sind. Ein schmerzfreier kürzerer Bereich kann eine bessere Wahl sein als ein tiefer, schmerzhafter.`},{title:`Praktische Checks`,text:`Achte bei einer Kniebeuge darauf, ob deine Füße am Boden bleiben, dein Rumpf kontrolliert bleibt und sich Knie und Hüften angenehm bewegen. Prüfe beim Überkopfdrücken, ob deine Arme ohne starkes Hohlkreuz nach oben reichen. Wenn eine Bewegung unten oder oben unkontrolliert wird, ändere die Tiefe, den Griff oder die Übungsvariante.`},{title:`Deinen Bereich erweitern`,text:`Finde zuerst den Bereich, den du kontrollieren kannst, wiederhole ihn dann zuverlässig und erweitere ihn danach, wenn das nützlich und angenehm ist. Der Bewegungsumfang ist eine Trainingsvariable unter anderen, wie Last, Wiederholungen und Stabilität.`},{title:`TrainUp nutzen`,text:`Wenn die Bewegung in einem Körperbereich eingeschränkt ist, füge sie im Profil als Einschränkung hinzu, mit Notizen, damit der Plan passende Übungen wählt. TrainUp kann nicht erkennen, ob eingeschränkte Bewegung von einem medizinischen Problem kommt. Wenn eine Einschränkung schmerzhaft ist und nicht verschwindet, lass sie von einer Ärztin, einem Arzt oder einer Physiotherapeutin bzw. einem Physiotherapeuten beurteilen.`}];var r=[{label:`ACSM-Positionspapier 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`WHO-Leitlinien zur Aktivität`,url:`https://pmc.ncbi.nlm.nih.gov/articles/PMC9219310/`}];var t={sections:i,sources:r};export{t as default,i as sections,r as sources};